/// The two network tools, and the shared HTTP plumbing they need.
///
/// GENERATED by the split of `tools.zig`, then edited by hand. It lives in
/// its own file so it can be tested on its own, without the TUI.
const std = @import("std");
const dispatch = @import("dispatch.zig");
const common = @import("common.zig");
const http = @import("../lib/http_client.zig");
const web = @import("../lib/web.zig");
const agent = @import("../agent.zig");

/// Hard cap on a web response. 200 KB of text is plenty to read a doc and
/// keeps an endless page (a listing of 50 000 links) from blowing up the turn's
/// context.
pub const web_hard_cap = 200 * 1024;

/// `web_fetch`: GET a URL and return the content as readable text.
///
/// The body ALWAYS goes through `web.htmlToText` when it looks like HTML, because
/// spending context on 300 KB of tags is throwing it away. JSON or plain text
/// pass through untouched.
pub fn toolWebFetch(io: std.Io, obj: std.json.ObjectMap, arena: std.mem.Allocator) ![]const u8 {
    const url = common.getStr(obj, "url") orelse
        return "error: web_fetch needs a `url` (http:// or https://)";
    const trimmed = std.mem.trim(u8, url, " \t\r\n");
    if (!isHttpUrl(trimmed)) {
        return std.fmt.allocPrint(arena, "error: only http:// and https:// URLs can be fetched, got: {s}", .{trimmed});
    }

    // The credential endpoints, before anything else happens.
    //
    // `web_fetch` asks for NO permission (see `needsPermission`) while `bash` does, so
    // this is the one door into the machine that the user never opens. That makes it a
    // permission question, not a sandbox question: a model can always reach the same
    // address with `curl` through `bash`, behind a dialog. What this removes is the case
    // where a page the model READ tells it to fetch an internal address and the answer
    // lands in the context and on the user's screen with nobody asked.
    if (web.isCredentialEndpoint(trimmed)) {
        return std.fmt.allocPrint(
            arena,
            "refused: {s} is a cloud instance-metadata endpoint, which serves credentials (AWS, GCP, Azure and DigitalOcean all use link-local for it). " ++
                "Fetching it would put a key in the transcript. " ++
                "If you genuinely need a private address, ZODE_WEB_ALLOW_LOCAL=1 allows the private ranges " ++
                "-- and `bash` with `curl` reaches it behind a permission dialog either way.",
            .{web.urlHost(trimmed)},
        );
    }
    if (web.isPrivateHost(trimmed) and !allowLocal()) {
        return std.fmt.allocPrint(
            arena,
            "refused: {s} is a loopback or private address, and `web_fetch` asks for no permission, so reaching it would be the one thing on this machine that never got your say. " ++
                "Set ZODE_WEB_ALLOW_LOCAL=1 if that is what you want (fetching your own dev server is a normal thing to do), or use `bash` with curl, which does ask.",
            .{web.urlHost(trimmed)},
        );
    }

    var max_bytes: usize = common.max_tool_output;
    if (common.getInt(obj, "max_bytes")) |mb| {
        if (mb > 0) max_bytes = @min(@as(usize, @intCast(mb)), web_hard_cap);
    }

    var h = http.Http.init(arena, io);
    defer h.deinit();

    const res = h.getWithHeaders(trimmed, &browserHeaders()) catch |err| {
        return std.fmt.allocPrint(arena, "error fetching {s}: {t}", .{ trimmed, err });
    };
    defer h.freeBody(res.body);

    const body = res.body;
    // A compressed body is not text: saying so is infinitely better than
    // returning binary and letting the model read it as if it were words.
    if (looksCompressed(body)) |kind| {
        return std.fmt.allocPrint(arena, "{s} answered with {s}-encoded content that zode cannot decode. Try a different URL (a .json or .txt endpoint usually works).", .{ trimmed, kind });
    }
    // A 4xx/5xx is information too: return the status and whatever the
    // server said, which is where the real reason is ("Model access is disabled").
    if (res.status < 200 or res.status >= 300) {
        return std.fmt.allocPrint(arena, "HTTP {d} {s}\n{s}", .{
            res.status,
            trimmed,
            body[0..@min(body.len, 2000)],
        });
    }

    const is_html = looksLikeHtml(body);
    const text = if (is_html) web.htmlToText(arena, body) else body;

    if (text.len == 0) return "(empty body)";

    // CAREFUL: the result is COPIED into memory owned by the arena. Returning a slice
    // of the HTTP buffer is a time bomb: the `defer freeBody` above
    // releases it when this function returns, and the ArenaAllocator REUSES
    // that memory in the next allocation (the one from `client.deinit`'s pool, the
    // buffer's own growth…). The caller read `0xAA` where the JSON
    // should have been. It goes through the truncation and the short path, and only with
    // an arena: that is why it never showed up in the network tests.
    var out: std.ArrayList(u8) = .empty;
    if (text.len <= max_bytes) {
        out.appendSlice(arena, text) catch return "out of memory building the answer";
    } else {
        // Cut at a line boundary: cutting in the middle of a word leaves
        // garbage that the model keeps thinking is the end of the
        // document.
        var cut = max_bytes;
        while (cut > 0 and text[cut] != '\n') cut -= 1;
        if (cut < max_bytes / 2) cut = max_bytes; // page with no line breaks: hard cut
        out.appendSlice(arena, text[0..cut]) catch return "out of memory building the answer";
        out.print(arena, "\n\n… (truncated at {d} of {d} bytes; ask for the rest with a deeper request)", .{ cut, text.len }) catch {};
    }
    return out.items;
}

/// `web_search`: DuckDuckGo results (`html/` endpoint, no API key).
///
/// It is a scrape, and it will break the day they change one of the HTML classes.
/// When that happens, the error says so (with the alternative) instead of returning an
/// empty list, which the model would interpret as "there are no results".
pub fn toolWebSearch(io: std.Io, obj: std.json.ObjectMap, arena: std.mem.Allocator) ![]const u8 {
    const query = common.getStr(obj, "query") orelse
        return "error: web_search needs a `query`";
    const q = std.mem.trim(u8, query, " \t\r\n");
    if (q.len == 0) return "error: empty query";

    var max_results: usize = 8;
    if (common.getInt(obj, "max_results")) |mr| {
        if (mr > 0) max_results = @min(@as(usize, @intCast(mr)), 20);
    }

    // DDG's `html/` endpoint is the one that asks for neither JS nor a key. The query goes
    // percent-encoded with `std.Uri`'s encoder (by hand people forget the `&` and
    // the `+`, and the search reaches the server in pieces).
    var url_buf: [1024]u8 = undefined;
    var uw: std.Io.Writer = .fixed(&url_buf);
    uw.writeAll("https://html.duckduckgo.com/html/?q=") catch return "error: query too long";
    // CAREFUL: `std.Uri.Writer` is NOT `pub` in 0.16, so the query component
    // encoder cannot be used from here. We percent-encode by
    // hand, which for a query is four characters.
    percentEncodeQuery(q, &uw) catch return "error: query too long";
    const url = uw.buffered();

    var h = http.Http.init(arena, io);
    defer h.deinit();

    const res = h.getWithHeaders(url, &browserHeaders()) catch |err| {
        return std.fmt.allocPrint(arena, "error searching \"{s}\": {t}", .{ q, err });
    };
    defer h.freeBody(res.body);

    if (res.status < 200 or res.status >= 300) {
        return engineRefused(arena, q, res.status);
    }

    if (web.searchResults(arena, res.body, max_results).len > 0) {
        return web.searchResults(arena, res.body, max_results);
    }
    h.freeBody(res.body);

    // SECOND ENDPOINT, and this is the whole improvement: `html/` answering 200
    // with a layout we do not know used to be the end of the road, and the model
    // was told the engine had no results for a query it HAD answered. `lite/` is
    // a different page of the same engine with different classes (`lib/web.zig`
    // parses both), so a layout change on one is a retry, not a failure.
    var url2_buf: [1024]u8 = undefined;
    var lite_w: std.Io.Writer = .fixed(&url2_buf);
    lite_w.writeAll("https://lite.duckduckgo.com/lite/?q=") catch return searchFailed(arena, q);
    percentEncodeQuery(q, &lite_w) catch return searchFailed(arena, q);
    const url2 = lite_w.buffered();

    const res2 = h.getWithHeaders(url2, &browserHeaders()) catch |err| {
        return std.fmt.allocPrint(arena, "error searching \"{s}\": {t} (and the fallback endpoint could not be reached either)", .{ q, err });
    };
    defer h.freeBody(res2.body);
    // The status is carried into the message instead of being dropped. Before, a
    // 202 here and a 200 with an unreadable page both arrived as the same "no
    // results could be parsed", and those are two completely different things: one
    // is the engine refusing this client, the other is our scraper being out of
    // date.
    if (res2.status < 200 or res2.status >= 300) return engineRefused(arena, q, res2.status);

    if (web.liteSearchResults(arena, res2.body, max_results).len > 0) {
        return web.liteSearchResults(arena, res2.body, max_results);
    }
    return searchFailed(arena, q);
}

pub fn browserHeaders() [3]http.Http.ExtraHeader {
    return .{
        .{ .name = "user-agent", .value = web.user_agent },
        .{ .name = "accept", .value = "text/html,application/json,text/plain;q=0.9,*/*;q=0.8" },
        // CAREFUL: you cannot leave `accept-encoding` out and trust things. `std.http`
        // sets `accept_encoding = .omit` (meaning "don't send the header"), and without
        // it GitHub and friends reply gzip: the model eats 16 KB of unreadable bytes
        // and has no idea what the page says. We ask for `identity`
        // explicitly, which is the only way to say "uncompressed" with
        // std, which does not decompress transparently.
        .{ .name = "accept-encoding", .value = "identity" },
    };
}

/// Did the body come compressed? (zstd, gzip, brotli…)
///
/// Safety net for when a server ignores `accept-encoding: identity`:
/// a message saying "it came compressed" is infinitely better than 16 KB of
/// binary that the model reads as text.
pub fn looksCompressed(body: []const u8) ?[]const u8 {
    if (body.len < 2) return null;
    // gzip 1f 8b, zstd 28 b5 2f fd, brotli (no fixed magic: many sites serve it
    // without a recognizable header, and it is detected by invalid UTF-8 below).
    if (body[0] == 0x1f and body[1] == 0x8b) return "gzip";
    if (body[0] == 0x28 and body[1] == 0xb5 and body.len >= 4 and body[2] == 0x2f and body[3] == 0xfd) return "zstd";
    // Generic binary: many NULs or stray control bytes.
    var ctrl: usize = 0;
    const probe = body[0..@min(body.len, 512)];
    for (probe) |b| {
        if (b < 0x09 or (b > 0x0d and b < 0x20)) ctrl += 1;
    }
    if (probe.len > 32 and ctrl * 4 > probe.len) return "binary";
    return null;
}

/// What the model is told when neither endpoint could be parsed.
///
/// It says what happened AND what to do, because "no results parsed" reads as
/// "nothing exists on the internet about this", and the model then tells the user
/// that.
/// The search ENGINE refused the request, which is not our bug and not the
/// model's fault either.
///
/// DuckDuckGo answers HTTP 202 with a full HTML page (an anomaly-detection
/// challenge, measured on 2026-10-04 with four consecutive requests from one
/// machine), so "the endpoint sent nothing parseable" and "the endpoint sent a
/// captcha" arrive at the parser as the same unreadable HTML. Saying "the HTML
/// did not match what this build knows how to read" there sends the model off to
/// rephrase a query that was perfectly fine, and it is what made the live test
/// flaky instead of skipped.
pub fn engineRefused(arena: std.mem.Allocator, q: []const u8, status: u16) []const u8 {
    return switch (status) {
        // 202 is what DuckDuckGo uses to throttle; it arrives as a captcha page.
        202, 429 => std.fmt.allocPrint(
            arena,
            "the search engine is refusing requests from this machine right now (HTTP {d} for \"{s}\"). That is rate limiting, not a bad query: do NOT rephrase it and do NOT retry in a loop. Wait, or answer from what you already have, or fetch a URL you already know with web_fetch.",
            .{ status, q },
        ) catch "the search engine is rate limiting this machine",
        else => std.fmt.allocPrint(
            arena,
            "the search engine answered HTTP {d} for \"{s}\". That is a problem on their side, not a bad query, and not something to rephrase.",
            .{ status, q },
        ) catch "the search engine returned an error",
    };
}

pub fn searchFailed(arena: std.mem.Allocator, q: []const u8) []const u8 {
    return std.fmt.allocPrint(
        arena,
        "no results could be parsed for \"{s}\". Both search endpoints answered, and their HTML did not match what this build knows how to read. Do NOT read that as \"there is nothing about this\": rephrase the query, or fetch a URL you already know with web_fetch.",
        .{q},
    ) catch "the search could not be read; rephrase the query or fetch a URL you know";
}

/// Percent-encoding of a query string, by hand.
///
/// `std.Uri.Writer` (which does know how) is not `pub` in 0.16, and `std.Uri`
/// only exposes the encoder internally. There are four reserved characters and it is one
/// line; what matters is that `&` and `+` are accounted for: without them, "zod & mcp"
/// reaches the server as two different searches.
pub fn percentEncodeQuery(raw: []const u8, w: *std.Io.Writer) !void {
    for (raw) |c| {
        const safe = std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.' or c == '~';
        if (safe) {
            try w.writeByte(c);
        } else if (c == ' ') {
            try w.writeByte('+');
        } else {
            try w.print("%{X:0>2}", .{c});
        }
    }
}

/// `ZODE_WEB_ALLOW_LOCAL=1` lets `web_fetch` reach loopback and the private ranges.
///
/// It is one variable and not a `--allow-local` flag because the thing it is for is a
/// standing preference ("I fetch my own dev server from here"), not a per-call decision.
fn allowLocal() bool {
    const v = agent.environ_global orelse return false;
    const s = v.get("ZODE_WEB_ALLOW_LOCAL") orelse return false;
    return s.len > 0 and !std.mem.eql(u8, s, "0") and !std.mem.eql(u8, s, "false");
}

pub fn isHttpUrl(url: []const u8) bool {
    if (std.mem.startsWith(u8, url, "http://")) return true;
    if (std.mem.startsWith(u8, url, "https://")) return true;
    return false;
}

/// Is the body HTML?
///
/// It is deduced from the body and NOT from `content-type`: that header lives in
/// `receiveHead`'s redirect buffer, which dies when the request returns (see the note in
/// `http_client.JsonResult`). A server can also send `text/plain` with
/// HTML inside, or the other way round, so the header was not to be trusted either.
///
/// It looks at the start of the document for `<!doctype html`, `<html`, `<head` or
/// `<body`, which is where any template puts them, and rejects what starts
/// with `{` or `[` (JSON) or with `#!` (a gist's shebang).
pub fn looksLikeHtml(body: []const u8) bool {
    const head = body[0..@min(body.len, 1024)];
    if (head.len == 0) return false;
    if (head[0] == '{' or head[0] == '[') return false;
    const trimmed = std.mem.trimStart(u8, head, " \t\r\n\u{feff}");
    if (std.mem.startsWith(u8, trimmed, "#!")) return false;
    return std.ascii.indexOfIgnoreCase(trimmed, "<!doctype html") != null or
        std.ascii.indexOfIgnoreCase(trimmed, "<html") != null or
        std.ascii.indexOfIgnoreCase(trimmed, "<head") != null or
        std.ascii.indexOfIgnoreCase(trimmed, "<body") != null;
}

/// `true` if the error is a network error (and the test is skipped) instead of a real failure.
pub fn isNetError(err: anyerror) bool {
    return switch (err) {
        error.ConnectionRefused,
        error.ConnectionResetByPeer,
        error.HostLackingDnsResolver,
        error.TemporaryNameServerFailure,
        error.NameServerFailure,
        error.UnknownHostName,
        error.ConnectionTimedOut,
        error.NetworkUnreachable,
        error.SocketNotConnected,
        => true,
        else => false,
    };
}

test "the web tools ask for no permissions (they are reads)" {
    // Asking for confirmation on every internet query turns the agent loop into
    // an interrogation. Same criterion as read/grep.
    try std.testing.expect(!dispatch.needsPermission("web_fetch"));
    try std.testing.expect(!dispatch.needsPermission("web_search"));
    try std.testing.expect(dispatch.needsPermission("write"));
}

test "web_fetch and web_search appear in the JSON with their description" {
    try std.testing.expect(std.mem.indexOf(u8, dispatch.toolsJson(), "\"web_fetch\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, dispatch.toolsJson(), "\"web_search\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, dispatch.toolsJson(), "html.duckduckgo.com") == null); // the endpoint lives in the code, not in the prompt
}

test "web_fetch rejects non-http(s) without touching the network" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const out = try dispatch.execute(std.testing.io, "web_fetch", "{\"url\":\"file:///etc/passwd\"}", arena_state.allocator(), null, null);
    try std.testing.expect(std.mem.indexOf(u8, out, "only http:// and https://") != null);
}

test "web_fetch without url says so" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const out = try dispatch.execute(std.testing.io, "web_fetch", "{}", arena_state.allocator(), null, null);
    try std.testing.expect(std.mem.indexOf(u8, out, "needs a `url`") != null);
}

test "web_search without query says so" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const out = try dispatch.execute(std.testing.io, "web_search", "{}", arena_state.allocator(), null, null);
    try std.testing.expect(std.mem.indexOf(u8, out, "needs a `query`") != null);
}

test "percentEncodeQuery escapes what breaks a URL" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    var buf: [64]u8 = undefined;
    var w: std.Io.Writer = .fixed(&buf);
    try percentEncodeQuery("zod & mcp/nuevo+1", &w);
    try std.testing.expectEqualStrings("zod+%26+mcp%2Fnuevo%2B1", w.buffered());
}

test "web_fetch for real: the HTML arrives as text, not as tags" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const out = dispatch.execute(std.testing.io, "web_fetch", "{\"url\":\"https://example.com/\"}", arena_state.allocator(), null, null) catch |err| {
        if (isNetError(err)) return error.SkipZigTest;
        return err;
    };
    // CAREFUL: example.com changes its text every so often; the test checks the
    // SHAPE (no tags, sentences with spaces) and not the exact sentence. A
    // test that fails because a site changed its copy is worthless.
    try std.testing.expect(out.len > 40);
    // The readable text carries no tags: if the HTTP buffer had been
    // released, fill bytes (`0xAA`) would show up here instead of the sentence.
    try std.testing.expect(std.mem.indexOf(u8, out, "<html") == null);
    try std.testing.expect(std.mem.indexOf(u8, out, "<div") == null);
    try std.testing.expect(std.mem.indexOf(u8, out, "documentation examples") != null);
}

test "web_search for real: returns results with a URL" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const out = dispatch.execute(std.testing.io, "web_search", "{\"query\":\"zig programming language\",\"max_results\":3}", arena_state.allocator(), null, null) catch |err| {
        if (isNetError(err)) return error.SkipZigTest;
        return err;
    };
    // A RATE LIMIT is not a broken scraper, and DuckDuckGo answers HTTP 202 with
    // no results in the body when it decides this process is asking too often
    // (measured on 2026-10-04, repeatedly, from one machine).
    //
    // The test was failing on that, which is worse than useless: a red suite that
    // is red for reasons outside the code trains everyone to ignore it, and then
    // the one day the scraper really does break nobody is looking.
    //
    // So the two are separated: 202 with no results is a SKIP (the endpoint is
    // rate-limiting), and 200 with no parseable results is still a FAILURE
    // (the HTML changed, which is what this test is for).
    if (looksRateLimited(out)) return error.SkipZigTest;

    try std.testing.expect(std.mem.indexOf(u8, out, "1. ") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "http") != null);
}

/// The message the tool gives when the search endpoint answered but had nothing
/// to hand over. A layout change and a rate limit both mean "no results", and
/// only one of them is our bug.
fn looksRateLimited(out: []const u8) bool {
    if (std.mem.indexOf(u8, out, "1. ") != null) return false; // it worked
    // Keyed on the tool's OWN words, not on a guess: `engineRefused` is the one
    // place that knows the endpoint answered with a refusal, and this test used
    // to look for "rate"/"202" in free text, which missed the actual message and
    // made the suite flaky for a day.
    return std.mem.indexOf(u8, out, "rate limiting") != null or
        std.mem.indexOf(u8, out, "refusing requests") != null or
        std.mem.indexOf(u8, out, "problem on their side") != null;
}

test "engineRefused tells the ENGINE refusing us apart from OUR scraper being stale" {
    // They used to produce the SAME sentence. Measured on 2026-10-04:
    // DuckDuckGo answers HTTP 202 with a full anomaly-detection HTML page, four
    // consecutive times from one machine, and the parser saw unreadable HTML —
    // exactly what a layout change looks like from in here.
    //
    // The consequences were real on both sides: the model was told to rephrase a
    // query that was fine, and the live test went red for a reason that had
    // nothing to do with the code.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();

    const throttled = engineRefused(a, "zig language", 202);
    try std.testing.expect(std.mem.indexOf(u8, throttled, "rate limiting") != null);
    // It has to say what NOT to do, or the model rephrases and retries.
    try std.testing.expect(std.mem.indexOf(u8, throttled, "do NOT rephrase") != null);
    try std.testing.expect(std.mem.indexOf(u8, throttled, "do NOT retry") != null);
    try std.testing.expect(std.mem.indexOf(u8, throttled, "web_fetch") != null);

    // Any other status is still "their side", and still not a bad query.
    for ([_]u16{ 403, 500, 503 }) |st| {
        const other = engineRefused(a, "q", st);
        try std.testing.expect(std.mem.indexOf(u8, other, "their side") != null);
        try std.testing.expect(std.mem.indexOf(u8, other, "not something to rephrase") != null);
    }

    // And the stale-scraper message stays DIFFERENT, because that one IS our bug
    // and it must not be skipped by the test.
    const stale = searchFailed(a, "q");
    try std.testing.expect(std.mem.indexOf(u8, stale, "did not match what this build knows") != null);
    try std.testing.expect(std.mem.indexOf(u8, stale, "rate limiting") == null);
}

test "looksRateLimited never mistakes a real result for a throttle" {
    // A result whose title happens to contain the word "rate" must not be
    // skipped, or the test would pass while the scraper was broken.
    const good = "1. Rate limiting in nginx\nhttps://example.com\n2. Other\nhttps://b.example";
    try std.testing.expect(!looksRateLimited(good));
    // And both real throttle messages are caught.
    try std.testing.expect(looksRateLimited("the search engine is refusing requests from this machine right now (HTTP 202 for \"q\"). That is rate limiting"));
    try std.testing.expect(looksRateLimited("the search engine answered HTTP 503 for \"q\". That is a problem on their side"));
}

test "web_fetch refuses the credential endpoints and says which host it was" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var obj: std.json.ObjectMap = .{};
    try obj.put(arena, "url", .{ .string = "http://169.254.169.254/latest/meta-data/" });
    const out = try toolWebFetch(std.testing.io, obj, arena);

    // It has to NAME the host: "refused" alone leaves the model to guess which of a
    // dozen URLs in the page it cannot use.
    try std.testing.expect(std.mem.indexOf(u8, out, "169.254.169.254") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "refused") != null);
    // And to say what to do, because "refused" with no way forward is a dead end the
    // model will route around with `bash`.
    try std.testing.expect(std.mem.indexOf(u8, out, "ZODE_WEB_ALLOW_LOCAL") != null);
}

test "web_fetch refuses loopback, and a public URL is not touched" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var obj: std.json.ObjectMap = .{};
    try obj.put(arena, "url", .{ .string = "http://127.0.0.1:8080/admin" });
    const out = try toolWebFetch(std.testing.io, obj, arena);
    // It must fail BEFORE the network: the refusal text is there and there is no
    // HTTP status in it.
    try std.testing.expect(std.mem.indexOf(u8, out, "127.0.0.1") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "permission") != null);

    // And `isHttpUrl` still accepts a public one, so the guard is not just "refuse all".
    try std.testing.expect(isHttpUrl("https://example.com/"));
    try std.testing.expect(!web.isPrivateHost("https://example.com/"));
}
